import{_ as e,c as s,aU as i,a as n}from"./chunks/framework.DP-R0N-M.js";const t="/assets/goland01.DtO3NdIu.png",k=JSON.parse('{"title":"go包管理","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/go/包管理.md","filePath":"note/back-end/go/包管理.md","lastUpdated":1757989980000}'),l={name:"note/back-end/go/包管理.md"};function o(d,a,p,r,h,c){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="go包管理" tabindex="-1">go包管理 <a class="header-anchor" href="#go包管理" aria-label="Permalink to &quot;go包管理&quot;">​</a></h1><p>专门开一篇来讲，因为需要注意的点还是挺多的。</p><p>你需要注意的是，</p><ol><li>同一个文件夹下，package的名字要一样。（不一样则会编译报错）</li><li>入口文件一般都在根目录下，并且package名字一定是main，并且只有一个<code>main()</code>入口函数</li><li>其他子文件夹的package名字最好和文件夹名字保持一致。（不强求）</li><li>每个项目都需要一个mod文件，mod文件中定义了模块的模块名，其他文件引入的话，同package直接引入，但是需要注意，要大写！！！大写表示public</li><li>引入不同包的函数，需要这样导入<code>&quot;your-module-name/web&quot;</code> (替换 your-module-name 为你实际在 go.mod 中定义的模块名)</li></ol><h2 id="多文件引用执行" tabindex="-1">多文件引用执行 <a class="header-anchor" href="#多文件引用执行" aria-label="Permalink to &quot;多文件引用执行&quot;">​</a></h2><p>比如demo文件夹下有两个文件，main.go 和 test.go , main.go要引入test.go文件的方法。需要在goland中稍微配置一下，不然会报错，或者用命令行运行。</p><p><code>在Go语言中，同一个包（package main）下的多个文件在编译时会被视为同一个模块，但必须同时指定所有文件进行编译</code></p><h3 id="用命令行的方式" tabindex="-1">用命令行的方式 <a class="header-anchor" href="#用命令行的方式" aria-label="Permalink to &quot;用命令行的方式&quot;">​</a></h3><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编译并运行（推荐）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.go</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>或者 , 但是需要注意的是，window下不支持通配符语法，你需要在git命令行环境下执行才可以。。。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.go</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="在goland中配置" tabindex="-1">在goland中配置 <a class="header-anchor" href="#在goland中配置" aria-label="Permalink to &quot;在goland中配置&quot;">​</a></h3><p>选目录和软件包都可以 <img src="`+t+'" alt=""></p>',13)])])}const m=e(l,[["render",o]]);export{k as __pageData,m as default};
